def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit from s_in to s_out."""
    # Simple approach: find first differing character position
    pos = -1
    for i, (c1, c2) in enumerate(zip(s_in, s_out)):
        if c1 != c2:
            pos = i
            break

    # If strings are different lengths, we'll handle that case
    if pos == -1:
        if len(s_in) != len(s_out):
            pos = min(len(s_in), len(s_out))
        else:
            return None  # No difference found

    # Find what we're replacing
    old_sub = s_in[pos:pos+1]  # Default to single char
    new_sub = s_out[pos:pos+1]  # Default to single char

    # For cases where we're replacing multiple chars
    if len(s_in) > pos and len(s_out) > pos:
        # Check if we're replacing a longer substring
        # Try to find longest match
        max_len = min(len(s_in) - pos, len(s_out) - pos)
        for l in range(max_len, 0, -1):
            if s_in[pos:pos+l] == s_out[pos:pos+l]:
                old_sub = s_in[pos:pos+l]
                new_sub = s_out[pos:pos+l]
                break

    return (old_sub, new_sub, pos)

def propose_rule_candidates(s_in, s_out):
    """Generate candidate replacement rules from a change."""
    # This is a simplified version - in practice this would be more complex
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)

    # Return most specific rule first
    if old_sub == new_sub:
        return []  # No change needed
    return [(old_sub, new_sub)]

def apply_rules(strings, rules):
    """Apply a sequence of rules to strings."""
    result = strings[:]
    for pattern, replacement in rules:
        result = [s.replace(pattern, replacement) for s in result]
    return result

def score_rules(inputs, outputs, rules):
    """Score how well rules perform on the corpus."""
    result = apply_rules(inputs, rules)
    correct = sum(1 for r, o in zip(result, outputs) if r == o)
    return correct / len(inputs)

def find_over_applications(inputs, outputs, rules):
    """Find which inputs are incorrectly modified by rules."""
    result = apply_rules(inputs, rules)
    over_apps = []
    for i, (inp, outp, res) in enumerate(zip(inputs, outputs, result)):
        if res != outp:
            over_apps.append((i, inp, res))
    return over_apps

def simulate_rule_chain(s, rules):
    """Simulate applying rules to a single string step by step."""
    trace = []
    current = s
    for pattern, replacement in rules:
        prev = current
        current = current.replace(pattern, replacement)
        trace.append({
            'pattern': pattern,
            'replacement': replacement,
            'before': prev,
            'after': current
        })
    return trace

def build_proxy_rules(pattern, replacement, proxy="__X__"):
    """Create proxy rules to prevent counterfeeding."""
    pre_rule = (pattern, proxy)
    post_rule = (proxy, replacement)
    return (pre_rule, post_rule)

